  const panelScale=elementLayoutScale(panel),panelRect=panel.getBoundingClientRect(),pw=panelRect.width||360,ph=panelRect.height||230;let x=clamp(b.right+18,12,W-pw-12),y=clamp(b.y,72,H-ph-12);if(b.right+pw+30>W){x=clamp(b.x-pw-18,12,W-pw-12);}if(W<700||x<b.right&&x+pw>b.x){x=clamp((W-pw)/2,12,W-pw-12);y=b.bottom+ph+18<H?b.bottom+18:Math.max(72,b.y-ph-18);if(y+ph>H-12)y=H-ph-12;}
